-- Neighborhood Guide for Cleveland's 34 neighborhoods, built on 2026-11-21 from official sources:
-- City of Cleveland open data (neighborhood, ward, police district, park and recreation center maps), Cleveland City Council
-- ward pages, City of Cleveland Division of Police, Cleveland Public Library, Greater Cleveland Food Bank and the City's 2025
-- community development funding map. Re-running replaces only the items this file created (sources other than 'Added by Nabora').
begin;
delete from neighborhood.guide_items where kind <> 'custom' and area_id in (select id from neighborhood.areas where region = 'Cleveland');
commit;
